/** A JSON-like object used for framework provider metadata. */
type JsonRecord = Record<string, unknown>;
/** Map of data part names to their payload shapes, e.g. `{ weather: { temp: number } }`. */
type DataTypes = Record<string, unknown>;
/** The input and output shapes associated with one scripted tool. */
type ToolDefinition = {
    input: unknown;
    output: unknown;
};
/** Map of tool names to their `input`/`output` shapes. Structurally compatible with the AI SDK's `UITools`. */
type ToolSet = Record<string, ToolDefinition>;
/** Options for scripting a typed or dynamic tool call. */
type ToolWriterOptions<TOOLS extends ToolSet, NAME extends keyof TOOLS> = {
    toolCallId?: string;
    title?: string;
    toolMetadata?: JsonRecord;
    providerExecuted?: boolean;
    input?: TOOLS[NAME]["input"];
    output?: TOOLS[NAME]["output"];
    errorText?: string;
    /** Script the call as a `dynamic-tool` part instead of a typed `tool-<name>` part. */
    dynamic?: boolean;
    /**
     * Pause the turn behind a user approval. `output` (or `errorText`) then
     * means "stream this after approval" instead of "resolve immediately";
     * denial streams `tool-output-denied` automatically.
     */
    needsApproval?: boolean;
    approvalId?: string;
};
/**
 * A human-in-the-loop tool call as a continuation turn sees it: the scripted
 * input, the user-submitted output (elicitation) or gated output (approval),
 * and the approval decision when one was requested.
 */
type PendingToolCall<TOOLS extends ToolSet> = {
    [NAME in keyof TOOLS & string]: {
        name: NAME;
        toolCallId: string;
        input: TOOLS[NAME]["input"];
        output: TOOLS[NAME]["output"] | undefined;
        approved?: boolean;
        denied?: boolean;
    };
}[keyof TOOLS & string];
/**
 * Per-part streaming controls. `delayMs` overrides the transport delay for
 * this part; `mode: "instant"` emits the whole text as a single delta instead
 * of word-by-word.
 */
type StreamTextOptions = {
    id?: string;
    delayMs?: number;
    mode?: "stream" | "instant";
};
/** Framework-neutral file attachment payload. */
type FilePayload = {
    mediaType: string;
    filename?: string;
    url: string;
    providerMetadata?: JsonRecord;
};
/** Framework-neutral file attached to a reasoning part. */
type ReasoningFilePayload = {
    mediaType: string;
    filename?: string;
    url: string;
    providerMetadata?: JsonRecord;
};
/** Framework-neutral URL source citation. */
type SourceUrlPayload = {
    sourceId: string;
    url: string;
    title?: string;
    providerMetadata?: JsonRecord;
};
/** Framework-neutral document source citation. */
type SourceDocumentPayload = {
    sourceId: string;
    mediaType: string;
    title: string;
    filename?: string;
    providerMetadata?: JsonRecord;
};
/**
 * A typed `data-<name>` part input. Repeating an `id` updates the previous
 * part in place (reconciliation); `transient` parts stream but never
 * materialize into message parts.
 */
type DataEventInput<DATA extends DataTypes> = {
    [NAME in keyof DATA & string]: {
        type: `data-${NAME}`;
        id?: string;
        data: DATA[NAME];
        transient?: boolean;
    };
}[keyof DATA & string];
/** Prefixes used by the deterministic chat id generators. */
type ChatIdsOptions = {
    messageIdPrefix?: string;
    toolCallIdPrefix?: string;
    sourceIdPrefix?: string;
    approvalIdPrefix?: string;
};
/** Chat-wide options: id prefixes plus the fixed clock used for default metadata. */
type ChatOptions = ChatIdsOptions & {
    now?: Date | string;
};
/** Transport options. `delayMs` is the delay between text/reasoning deltas; defaults to 50ms. */
type TurnStreamOptions = {
    delayMs?: number;
};
/** Options for one user turn. */
type ChatUserOptions<METADATA> = {
    id?: string;
    metadata?: METADATA;
    files?: Array<FilePayload & {
        type?: "file";
    }>;
};
/** Options for one assistant turn. */
type ChatAssistantOptions<METADATA> = {
    id?: string;
    metadata?: METADATA;
};

/**
 * Lifecycle handle returned by `writer.tool()`. Chain `sleep()` between the
 * input and its `output()`/`error()`/`denied()` resolution to script tool
 * latency.
 */
type ToolHandle<OUTPUT> = {
    sleep(delayMs: number): ToolHandle<OUTPUT>;
    output(output: OUTPUT): ToolHandle<OUTPUT>;
    error(errorText?: string): ToolHandle<OUTPUT>;
    denied(): ToolHandle<OUTPUT>;
};
/**
 * The fluent writer DSL handed to `assistant(({ writer }) => …)`. Each call
 * appends events to the turn's log in order; every method chains except
 * `tool()`, which returns a {@link ToolHandle}.
 */
type EventWriter<DATA extends DataTypes, TOOLS extends ToolSet> = {
    text(text?: string, options?: StreamTextOptions): EventWriter<DATA, TOOLS>;
    reasoning(text?: string, options?: StreamTextOptions): EventWriter<DATA, TOOLS>;
    sleep(delayMs: number): EventWriter<DATA, TOOLS>;
    data(part: DataEventInput<DATA>): EventWriter<DATA, TOOLS>;
    error(errorText?: string): EventWriter<DATA, TOOLS>;
    tool<NAME extends keyof TOOLS & string>(name: NAME, options?: ToolWriterOptions<TOOLS, NAME>): ToolHandle<TOOLS[NAME]["output"]>;
    sourceUrl(overrides?: Partial<SourceUrlPayload>): EventWriter<DATA, TOOLS>;
    sourceDocument(overrides?: Partial<SourceDocumentPayload>): EventWriter<DATA, TOOLS>;
    file(overrides?: Partial<FilePayload>): EventWriter<DATA, TOOLS>;
    reasoningFile(overrides?: Partial<ReasoningFilePayload>): EventWriter<DATA, TOOLS>;
    custom(kind?: string): EventWriter<DATA, TOOLS>;
    stepStart(): EventWriter<DATA, TOOLS>;
};

/**
 * A transport response for when no configured assistant response remains —
 * most commonly an exhausted chat (the user keeps sending past the end).
 * A string (one streamed text part), a parts array, or a writer callback
 * that also receives the incoming transcript. Note: fully unrecognized
 * transcripts replay the chat from the top rather than falling back.
 */
type ChatFallback<MESSAGE, PART, DATA extends DataTypes = DataTypes, TOOLS extends ToolSet = ToolSet, WRITER = EventWriter<DATA, TOOLS>> = string | PART[] | ((context: {
    writer: WRITER;
    messages: MESSAGE[];
}) => void);
/**
 * Transport options: `delayMs` between text and reasoning deltas (default 50,
 * explicit `undefined` disables delays) and an optional `fallback` used when
 * no configured assistant response remains instead of throwing.
 */
type ChatTransportOptions<MESSAGE, PART, DATA extends DataTypes = DataTypes, TOOLS extends ToolSet = ToolSet, WRITER = EventWriter<DATA, TOOLS>> = TurnStreamOptions & {
    fallback?: ChatFallback<MESSAGE, PART, DATA, TOOLS, WRITER>;
};
/**
 * The context handed to assistant writer callbacks. A continuation turn — a
 * callback turn scripted after a turn that pauses for user input — also
 * receives the live transcript and the resolved human-in-the-loop tool
 * calls; eager turns receive only the writer.
 */
type AssistantTurnContext<WRITER, MESSAGE, TOOLS extends ToolSet = ToolSet> = {
    writer: WRITER;
    messages?: MESSAGE[];
    toolCall?: PendingToolCall<TOOLS>;
    toolCalls?: Array<PendingToolCall<TOOLS>>;
};
/** A deterministic conversation: chain turns, then read them back or stream them through a transport. */
type Chat<MESSAGE, PART, TRANSPORT, METADATA = unknown, DATA extends DataTypes = DataTypes, TOOLS extends ToolSet = ToolSet, WRITER = EventWriter<DATA, TOOLS>> = {
    /** Scripts a user turn: one text part plus optional file attachments. */
    user(text?: string, options?: ChatUserOptions<METADATA>): Chat<MESSAGE, PART, TRANSPORT, METADATA, DATA, TOOLS, WRITER>;
    /**
     * Scripts an assistant turn from a string (one streamed text part), a
     * parts array (static parts, streamed instantly), or a writer callback
     * (full control over parts and timing). A callback turn scripted after a
     * paused turn — an unresolved tool call or `needsApproval` — becomes a
     * continuation: it materializes when the follow-up request arrives, with
     * the live transcript and resolved tool calls in its context.
     */
    assistant(input?: string | PART[] | ((context: AssistantTurnContext<WRITER, MESSAGE, TOOLS>) => void), options?: ChatAssistantOptions<METADATA>): Chat<MESSAGE, PART, TRANSPORT, METADATA, DATA, TOOLS, WRITER>;
    /** Scripts an assistant turn that streams a bare error chunk and ends. */
    error(errorText?: string): Chat<MESSAGE, PART, TRANSPORT, METADATA, DATA, TOOLS, WRITER>;
    /** Delays the next turn's stream. */
    sleep(delayMs: number): Chat<MESSAGE, PART, TRANSPORT, METADATA, DATA, TOOLS, WRITER>;
    /**
     * Returns clones of the first `count` configured messages, or all
     * materializable messages when omitted. Continuation turns have no message
     * without a live transcript, so `get` stops before the first one and
     * throws when `count` reaches past it.
     */
    get(count?: number): MESSAGE[];
    /**
     * Returns the next configured user message after the given transcript, or
     * `null` when none remain. Matches by message id, falling back to role and
     * text, without mutating the chat.
     */
    next(messages: readonly MESSAGE[]): MESSAGE | null;
    /** Creates the framework transport that streams configured assistant responses. */
    transport(options?: ChatTransportOptions<MESSAGE, PART, DATA, TOOLS, WRITER>): TRANSPORT;
};

export type { Chat as C, EventWriter as E, StreamTextOptions as S, ToolWriterOptions as T, ChatOptions as a };
